      "zh": "成年儿子因母亲拒绝交出四万美元而掌掴她后，玛格丽特仍准备了一桌早餐，却让哥哥迈克尔坐在了餐桌旁。埃文以为这又是一次毫无原则的退让，没想到迎接他的却是被冻结的贷款、被揭穿的伪造文件，以及一位母亲夺回房屋、财产和人生边界的反击。"
